#include "game_service.h"
#include <algorithm>
#include <limits>
namespace Snatcher {
namespace {
bool same(const GameSaveTransaction& a,const GameSaveTransaction& b){return a.serial==b.serial&&a.slot==b.slot&&a.beforeCounter==b.beforeCounter&&a.stagedCounter==b.stagedCounter&&a.existing==b.existing;}
bool owns(const GameServiceState& s,const GameSaveTransaction& t,std::string& error){if(!validateGameServiceState(s,error))return false;if(!s.pending||!same(s.write,t)){error="stale or foreign original save completion";return false;}return true;}
}
bool validateGameServiceState(const GameServiceState& s,std::string& error){error.clear();if(s.availability<kGameStorageUnknown||s.availability>kGameStorageReady||s.saveCounter>99||(!s.counterKnown&&s.saveCounter)||(!s.resultKnown&&s.lastWriteResult)||(s.resultKnown&&s.lastWriteResult!=0&&s.lastWriteResult!=1&&s.lastWriteResult!=255)){error="invalid native original-service facts";return false;}for(unsigned i=0;i<4;++i)if(!s.slots[i].known&&s.slots[i].occupied){error="unknown original slot cannot assert presence";return false;}
 if(s.pending){const GameSaveTransaction& t=s.write;if(!s.counterKnown||s.availability!=kGameStorageReady||!t.serial||t.serial!=s.serial||t.slot<1||t.slot>4||t.beforeCounter!=s.saveCounter||t.stagedCounter!=std::min<unsigned>(99,unsigned(t.beforeCounter)+1)||!s.slots[t.slot-1].known||t.existing!=s.slots[t.slot-1].occupied){error="invalid staged original save transaction";return false;}}
 else if(s.write.serial||s.write.slot||s.write.beforeCounter||s.write.stagedCounter||s.write.existing){error="inactive original save retains staged operation";return false;}return true;}
bool readGameStorageQuery(const GameServiceState& s,GameStorageQuery query,uint16_t& value,std::string& error){if(!validateGameServiceState(s,error))return false;uint16_t result=0;if(query==kGameStorageStatus){if(s.availability==kGameStorageUnknown){error="original storage availability has no backend facts";return false;}result=s.availability==kGameStorageReady?1:0;}else if(query==kGameLastWriteResult){if(!s.resultKnown){error="original save result has no completed service owner";return false;}result=s.lastWriteResult;}else if(query>=kGameSlot1&&query<=kGameSlot4){const GameSaveSlotFact& slot=s.slots[query-kGameSlot1];if(!slot.known){error="original slot presence has not been scanned";return false;}result=slot.occupied?1:0;}else{error="unknown original storage query";return false;}value=result;return true;}
bool beginGameSaveWrite(GameServiceState& s,unsigned slot,GameSaveTransaction& transaction,std::string& error){if(!validateGameServiceState(s,error))return false;if(s.pending||slot<1||slot>4||!s.counterKnown||s.availability!=kGameStorageReady||!s.slots[slot-1].known||s.serial==std::numeric_limits<uint64_t>::max()){error="original save request lacks ready slot/counter/backend ownership";return false;}GameSaveTransaction t;t.serial=s.serial+1;t.slot=uint8_t(slot);t.beforeCounter=s.saveCounter;t.stagedCounter=uint8_t(std::min<unsigned>(99,unsigned(s.saveCounter)+1));t.existing=s.slots[slot-1].occupied;s.serial=t.serial;s.write=t;s.pending=true;transaction=t;return true;}
bool finishGameSaveWrite(GameServiceState& s,const GameSaveTransaction& t,GameSaveOutcome outcome,std::string& error){if(!owns(s,t,error))return false;if(outcome<kGameSaveCommitted||outcome>kGameSaveIOFailure){error="unrecognized original save outcome";return false;}GameServiceState next=s;if(outcome==kGameSaveCommitted){next.saveCounter=t.stagedCounter;next.slots[t.slot-1].occupied=true;next.lastWriteResult=0;}else next.lastWriteResult=outcome==kGameSaveNoCapacity?1:255;next.resultKnown=true;next.pending=false;next.write=GameSaveTransaction();s=next;return true;}
bool abortGameSaveWrite(GameServiceState& s,const GameSaveTransaction& t,std::string& error){if(!owns(s,t,error))return false;s.pending=false;s.write=GameSaveTransaction();return true;}
bool previewCommittedGameSave(const GameServiceState& s,const GameSaveTransaction& t,GameServiceState& preview,std::string& error){GameServiceState next=s;if(!finishGameSaveWrite(next,t,kGameSaveCommitted,error))return false;preview=next;return true;}
bool resolveGameSaveResume(uint16_t resource,uint32_t outerEntry,const std::vector<uint32_t>& localEntries,GameSaveResume& resume,std::string& error){error.clear();if(resource<0x39||resource>0x5f||outerEntry>65535||localEntries.size()>16){error="original save resume owner outside scenario domain";return false;}for(uint32_t entry:localEntries)if(entry>65535){error="original local entry outside source word domain";return false;}GameSaveResume next;next.resource=resource;next.entry=uint16_t(localEntries.empty()?outerEntry:localEntries.front());resume=next;return true;}
namespace {
void put(std::vector<uint8_t>& b,uint64_t value,unsigned n){for(unsigned i=n;i;--i)b.push_back(uint8_t(value>>((i-1)*8)));}
uint64_t get(const std::vector<uint8_t>& b,size_t& at,unsigned n){uint64_t value=0;while(n--)value=(value<<8)|b[at++];return value;}
uint32_t crc(const std::vector<uint8_t>& b){uint32_t c=0xffffffff;for(uint8_t v:b){c^=v;for(unsigned i=0;i<8;++i)c=(c>>1)^((c&1)?0xedb88320u:0);}return c^0xffffffff;}
std::vector<uint8_t> wrap(const char* magic,const std::vector<uint8_t>& payload){std::vector<uint8_t> b(magic,magic+4);put(b,payload.size(),2);put(b,crc(payload),4);b.insert(b.end(),payload.begin(),payload.end());return b;}
bool unwrap(const std::vector<uint8_t>& b,const char* magic,std::vector<uint8_t>& payload,std::string& error){if(b.size()<10||b.size()>(std::string(magic)=="SGR2"?65545:2048)||!std::equal(b.begin(),b.begin()+4,magic)){error="unknown original-service record header/extent";return false;}size_t at=4;size_t count=size_t(get(b,at,2));uint32_t checksum=uint32_t(get(b,at,4));if(count!=b.size()-10){error="original-service payload length mismatch";return false;}std::vector<uint8_t> next(b.begin()+10,b.end());if(crc(next)!=checksum){error="original-service payload checksum mismatch";return false;}payload.swap(next);return true;}
bool discValid(const std::string& disc){if(disc.size()!=64)return false;for(char c:disc)if(!((c>='0'&&c<='9')||(c>='a'&&c<='f')))return false;return true;}
}
bool encodeGameServiceState(const GameServiceState& s,std::vector<uint8_t>& bytes,std::string& error){if(!validateGameServiceState(s,error))return false;if(s.pending){error="active original write is not a native save boundary";return false;}std::vector<uint8_t> p;put(p,s.availability,1);unsigned known=0,present=0;for(unsigned i=0;i<4;++i){if(s.slots[i].known)known|=1u<<i;if(s.slots[i].occupied)present|=1u<<i;}put(p,known,1);put(p,present,1);put(p,(s.counterKnown?1:0)|(s.resultKnown?2:0),1);put(p,s.saveCounter,1);put(p,s.lastWriteResult,2);put(p,s.serial,8);bytes=wrap("SGS1",p);return true;}
bool decodeGameServiceState(const std::vector<uint8_t>& bytes,GameServiceState& s,std::string& error){error.clear();std::vector<uint8_t> p;if(!unwrap(bytes,"SGS1",p,error))return false;if(p.size()!=15){error="original-service owner payload extent";return false;}size_t at=0;GameServiceState next;unsigned availability=unsigned(get(p,at,1)),known=unsigned(get(p,at,1)),present=unsigned(get(p,at,1)),flags=unsigned(get(p,at,1));if(availability>2||(known&~15u)||(present&~15u)||(flags&~3u)){error="original-service owner reserved bits";return false;}next.availability=GameStorageAvailability(availability);for(unsigned i=0;i<4;++i){next.slots[i].known=(known&(1u<<i))!=0;next.slots[i].occupied=(present&(1u<<i))!=0;}next.counterKnown=(flags&1)!=0;next.resultKnown=(flags&2)!=0;next.saveCounter=uint8_t(get(p,at,1));next.lastWriteResult=uint16_t(get(p,at,2));next.serial=get(p,at,8);if(!validateGameServiceState(next,error))return false;s=next;return true;}
bool validateGameSaveRecord(const GameSaveRecord& r,std::string& error){error.clear();if(!r.contextKnown||!discValid(r.disc)||r.scenarioStamps.size()!=39||r.packed.size()!=352||r.thumbnail.size()>48*1024||r.resource<0x39||r.resource>0x5f||r.resumeEntry==0xffff||r.counter>99||r.controllerMapping>5||r.cursorHistory.size()>3||r.elapsed.hours>99||r.elapsed.minutes>59||r.elapsed.seconds>59||r.elapsed.frames>59){error="incomplete or invalid original-game save context";return false;}for(uint16_t entry:r.cursorHistory)if(entry==0xffff){error="reserved original cursor history value";return false;}const GameSaveBookmark& b=r.bookmark;if(!b.known||b.presentation==0xffff||(b.presentation>>8)>=0x39||b.ambient>15||b.interaction>3){error="original save has no valid fresh presentation context";return false;}for(uint8_t a:b.actors)if(a!=0&&a!=0xc0&&(a<0x80||a>=0xc0)){error="invalid source compact actor control";return false;}return true;}
bool encodeGameSaveRecord(const GameSaveRecord& r,std::vector<uint8_t>& bytes,std::string& error){if(!validateGameSaveRecord(r,error))return false;std::vector<uint8_t> p(r.disc.begin(),r.disc.end());put(p,r.scenarioStamps.size(),1);for(uint64_t stamp:r.scenarioStamps)put(p,stamp,8);put(p,r.resource,2);put(p,r.resumeEntry,2);put(p,r.progression,2);put(p,r.controllerMapping|(r.sourcePolicy40?64:0)|(r.sourcePolicy80?128:0),1);put(p,r.pointerAnchorX,1);put(p,r.pointerAnchorY,1);put(p,r.counter,1);put(p,r.elapsed.hours,1);put(p,r.elapsed.minutes,1);put(p,r.elapsed.seconds,1);put(p,r.elapsed.frames,1);put(p,r.cursorHistory.size(),1);for(uint16_t entry:r.cursorHistory)put(p,entry,2);const GameSaveBookmark& b=r.bookmark;put(p,b.presentation,2);put(p,b.pcm,2);put(p,b.music,1);put(p,b.ambient|(b.interaction<<4)|(b.quiet?64:0)|(b.suppressed?128:0),1);p.insert(p.end(),b.actors.begin(),b.actors.end());p.insert(p.end(),r.packed.begin(),r.packed.end());if(!r.thumbnail.empty()){p.insert(p.end(),{'S','N','T','H'});put(p,r.thumbnail.size(),4);p.insert(p.end(),r.thumbnail.begin(),r.thumbnail.end());}bytes=wrap("SGR2",p);return true;}
bool decodeGameSaveRecord(const std::vector<uint8_t>& bytes,const std::string& expectedDisc,const std::vector<uint64_t>& expectedStamps,GameSaveRecord& r,std::string& error){error.clear();std::vector<uint8_t> p;if(bytes.size()>=4&&std::equal(bytes.begin(),bytes.begin()+4,"SGR1")){error="Legacy SGR1 PCM cache semantics are ambiguous; load a CE archive and create a fresh original slot";return false;}if(!unwrap(bytes,"SGR2",p,error))return false;if(p.size()<814||p.size()>820+8+48*1024||!discValid(expectedDisc)||expectedStamps.size()!=39){error="original-game record identity/extent";return false;}GameSaveRecord next;next.disc.assign(p.begin(),p.begin()+64);size_t at=64;if(get(p,at,1)!=39){error="original-game scenario stamp extent";return false;}for(unsigned i=0;i<39;++i)next.scenarioStamps.push_back(get(p,at,8));if(next.disc!=expectedDisc||next.scenarioStamps!=expectedStamps){error="original-game disc/source identity mismatch";return false;}next.resource=uint16_t(get(p,at,2));next.resumeEntry=uint16_t(get(p,at,2));next.progression=uint16_t(get(p,at,2));unsigned flags=unsigned(get(p,at,1));if(flags&0x38){error="original-game setting reserved bits";return false;}next.controllerMapping=uint8_t(flags&7);next.sourcePolicy40=(flags&64)!=0;next.sourcePolicy80=(flags&128)!=0;next.pointerAnchorX=uint8_t(get(p,at,1));next.pointerAnchorY=uint8_t(get(p,at,1));next.counter=uint8_t(get(p,at,1));next.elapsed.hours=uint8_t(get(p,at,1));next.elapsed.minutes=uint8_t(get(p,at,1));next.elapsed.seconds=uint8_t(get(p,at,1));next.elapsed.frames=uint8_t(get(p,at,1));unsigned histories=unsigned(get(p,at,1));if(histories>3||p.size()<814+2*histories){error="original-game history payload extent";return false;}for(unsigned i=0;i<histories;++i)next.cursorHistory.push_back(uint16_t(get(p,at,2)));GameSaveBookmark& b=next.bookmark;b.presentation=uint16_t(get(p,at,2));b.pcm=uint16_t(get(p,at,2));b.music=uint8_t(get(p,at,1));flags=unsigned(get(p,at,1));b.ambient=uint8_t(flags&15);b.interaction=uint8_t((flags>>4)&3);b.quiet=(flags&64)!=0;b.suppressed=(flags&128)!=0;for(uint8_t& actor:b.actors)actor=uint8_t(get(p,at,1));next.packed.assign(p.begin()+at,p.begin()+at+352);at+=352;
 if(at<p.size()){
  if(p.size()-at<8||!std::equal(p.begin()+at,p.begin()+at+4,"SNTH")){error="unknown original-save metadata extension";return false;}
  at+=4;size_t count=size_t(get(p,at,4));if(!count||count>48*1024||count!=p.size()-at){error="original-save thumbnail extent";return false;}
  next.thumbnail.assign(p.begin()+at,p.end());
 }
 b.known=next.contextKnown=true;if(!validateGameSaveRecord(next,error))return false;r=next;return true;}
bool decodeGameSaveMetadata(const std::vector<uint8_t>& bytes,GameSaveRecord& record,std::string& error){
 std::vector<uint8_t> payload;if(!unwrap(bytes,"SGR2",payload,error)||payload.size()<814||payload.size()>820+8+48*1024)return false;
 std::string disc(payload.begin(),payload.begin()+64);size_t at=64;if(get(payload,at,1)!=39)return false;
 std::vector<uint64_t> stamps;for(unsigned i=0;i<39;++i)stamps.push_back(get(payload,at,8));
 return decodeGameSaveRecord(bytes,disc,stamps,record,error);
}}
